test('tombstones stay in state and out of sight, newest first', () => {
  const state = { notes: {
    a: note('a', 'old', 1),
    b: note('b', 'new', 3),
    c: note('c', 'deleted', 2, { deleted: true }),
  } };
  assert.deepEqual(visibleNotes(state).map((n) => n.id), ['b', 'a']);
